                const next = !soundOn;
                setSoundOn(next);
                // Bật âm = user gesture → unlock AudioContext + beep xác nhận
                // để nhân viên biết loa hoạt động.
                if (next) {
                  getAudioCtx();
                  playBeep(880, 0.12, 0.25);
